`timescale 1ns/1ps
// Basys 3 top level - generated by scripts/make_experiments.py
module top_basys3 (
    input  wire        clk,                    // 100 MHz
    input  wire        btnC, btnU, btnL, btnR, // btnC = reset
    input  wire [15:0] sw,
    output wire [15:0] led,
    output wire [3:0]  an,
    output wire [6:0]  seg
);
    wire rst = btnC;
    wire en;   // one model step every 1/1000 s, slow enough to watch
    step_tick #(.STEP_HZ(1000)) u_tick (.clk(clk), .rst(rst), .tick(en));
    // four random inputs; sw[1] = 1 makes inputs 0 and 1 share one source (correlated)
    wire [15:0] ra, rb, rc, rd;
    lfsr16 #(.SEED(16'hACE1)) u_a (.clk(clk), .rst(rst), .en(en), .q(ra));
    lfsr16 #(.SEED(16'h1234)) u_b (.clk(clk), .rst(rst), .en(en), .q(rb));
    lfsr16 #(.SEED(16'hBEEF)) u_c (.clk(clk), .rst(rst), .en(en), .q(rc));
    lfsr16 #(.SEED(16'h5A5A)) u_d (.clk(clk), .rst(rst), .en(en), .q(rd));
    wire [15:0] p = {sw[7:4], 12'd0};                 // spike probability per step = sw[7:4] / 16
    wire [3:0] pre = sw[0] ? {rc < p, rb < p, (sw[1] ? ra : rd) < p, ra < p} : 4'b0000;
    wire post;  wire signed [31:0] v;  wire [127:0] w_bus;
    stdp_network u_net (.clk(clk), .rst(rst), .en(en), .learn(sw[2]), .pre(pre), .post(post), .v(v), .w_bus(w_bus));
    wire signed [31:0] w0 = w_bus[31:0], w1 = w_bus[63:32], w2 = w_bus[95:64], w3 = w_bus[127:96];
    wire signed [31:0] wsel = (sw[15:14] == 0) ? w0 : (sw[15:14] == 1) ? w1 : (sw[15:14] == 2) ? w2 : w3;
    wire spike_led;
    pulse_stretch u_ps (.clk(clk), .rst(rst), .in(post), .out(spike_led));
    wire signed [31:0] bar_val = wsel;
    bar15 #(.FULL(255)) u_bar (.val(bar_val), .leds(led[14:0]));
    assign led[15] = spike_led;
    wire signed [31:0] num = wsel;
    seg7_signed u_seg (.clk(clk), .value(num[15:0]), .an(an), .seg(seg));
endmodule
